// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        Reverter r = new Reverter();
        bool ok;
        // msg.sender here is this test contract, which is c's owner
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: any sendTo that pays a failing receiver must revert.
        assertTrue(ok == false, "sendTo succeeded despite failing receiver");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
